CREATE TABLE `users` (`id` TEXT NOT NULL, `householdId` TEXT NOT NULL, `email` TEXT NOT NULL, `displayName` TEXT NOT NULL, `avatarUrl` TEXT, `role` TEXT NOT NULL, `isPinProtected` INTEGER NOT NULL, `pinHash` TEXT, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `user_preferences` (`userId` TEXT NOT NULL, `theme` TEXT NOT NULL, `visibleTodoGroups` TEXT NOT NULL, `notificationPreferences` TEXT NOT NULL, `dailyResetTime` TEXT NOT NULL, `affirmationFrequency` INTEGER NOT NULL, `enableGamification` INTEGER NOT NULL, `enableBadges` INTEGER NOT NULL, `enableStreaks` INTEGER NOT NULL, `enableEfficiencyMetrics` INTEGER NOT NULL, `timerDefaultDuration` INTEGER NOT NULL, `autoLogoutTimeout` INTEGER NOT NULL, PRIMARY KEY(`userId`), FOREIGN KEY(`userId`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `current_user` (`id` TEXT NOT NULL, `userId` TEXT NOT NULL, `householdId` TEXT NOT NULL, `lastSwitchTime` INTEGER NOT NULL, `sessionStartTime` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`userId`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `affirmations` (`id` TEXT NOT NULL, `type` TEXT NOT NULL, `message` TEXT NOT NULL, `tone` TEXT NOT NULL, `ageAppropriatenessLevel` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
