CREATE TABLE `badges` (`id` TEXT NOT NULL, `householdId` TEXT NOT NULL, `userId` TEXT NOT NULL, `badgeType` TEXT NOT NULL, `name` TEXT NOT NULL, `description` TEXT, `iconUrl` TEXT, `earnedAt` INTEGER NOT NULL, `progress` INTEGER, `isLocked` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `streaks` (`id` TEXT NOT NULL, `userId` TEXT NOT NULL, `householdId` TEXT NOT NULL, `currentCount` INTEGER NOT NULL, `bestCount` INTEGER NOT NULL, `lastCompletionDate` TEXT, `startDate` TEXT, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `efficiency_metrics` (`id` TEXT NOT NULL, `taskId` TEXT NOT NULL, `userId` TEXT NOT NULL, `householdId` TEXT NOT NULL, `estimatedDurationMinutes` INTEGER, `actualDurationMinutes` INTEGER, `efficiencyPercentage` REAL, `completedAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`taskId`) REFERENCES `tasks`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`userId`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `sync_queue` (`id` TEXT NOT NULL, `taskId` TEXT NOT NULL, `userId` TEXT NOT NULL, `operation` TEXT NOT NULL, `payload` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `retryCount` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`taskId`) REFERENCES `tasks`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`userId`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `offline_update_queue` (`id` TEXT NOT NULL, `taskId` TEXT NOT NULL, `userId` TEXT NOT NULL, `updateType` TEXT NOT NULL, `payload` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `applied` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`taskId`) REFERENCES `tasks`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`userId`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
